 public static void Run(){Directory.CreateDirectory(Out);try{Empty();var rp=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Settings/PC_RPAsset.asset");GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;var result=MapSharedPropsBuilder.Build(Input);folder=result.assetDirectory;Check(result.prefabs.Count==74,"formal74");int old=0;foreach(var kv in result.prefabs.Where(x=>x.Key!="minecart_loaded")){var prev=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/MapSharedPropsGenerated/Pilot 7/"+(kv.Key.StartsWith("cnd")?"":"small-")+kv.Key+".prefab");if(!prev){var paths=AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/MapSharedPropsGenerated/Pilot 7"}).Select(AssetDatabase.GUIDToAssetPath);prev=paths.Select(AssetDatabase.LoadAssetAtPath<GameObject>).FirstOrDefault(x=>x&&x.name==kv.Key);}Check(prev,"old asset "+kv.Key);Check(Shape(prev.GetComponent<MeshFilter>().sharedMesh)==Shape(kv.Value.GetComponent<MeshFilter>().sharedMesh),"old geometry "+kv.Key);var bc=prev.GetComponentsInChildren<Collider>();var ac=kv.Value.GetComponentsInChildren<Collider>();Check(bc.Length==ac.Length,"actual collider count "+kv.Key);if(bc.Length>0)Check(ColliderSnapshot109.Capture(prev)==ColliderSnapshot109.Capture(kv.Value),"old collider "+kv.Key);old++;}Check(old==73,"all old73");
