 static void Fallbacks(){var raw=File.ReadAllText(Path.Combine(Input,"small_props.json"));var names=new List<string>();foreach(var tag in new[]{"missing","version","png","index","nan","nonSolid","circle","customHeight"}){var d=JsonUtility.FromJson<SmallPropsV1.Data>(raw);if(tag=="missing")d.mineCartLoadV1=null;else if(tag=="version")d.mineCartLoadV1.version=2;else if(tag=="png")d.mineCartLoadV1.textures.colour="bad";else if(tag=="index")d.mineCartLoadV1.assets[0].triangles[0]=999999;else if(tag=="nan")d.mineCartLoadV1.assets[0].positions[0]=float.NaN;else if(tag=="nonSolid")d.mineCartLoadV1.assets[0].radius=0;else if(tag=="customHeight")d.mineCartLoadV1.assets[0].height=1.4f;else if(tag=="circle"){var a=d.mineCartLoadV1.assets[0];a.shape=false;a.radius=.5f;a.height=.8f;a.circleColliders=new[]{new SmallPropsV1.CircleProxy{center=new[]{0f,0f,0f},radius=.5f,height=.8f}};}d.mineCartLoadV1=MineCartV1.Optional(d.mineCartLoadV1,true);bool valid=new[]{"nonSolid","circle","customHeight"}.Contains(tag);Check((d.mineCartLoadV1!=null)==valid,"fallback "+tag);Check(MineCartV1.Optional(d.mineCartV1)!=null,"empty cart remains valid "+tag);string f="Assets/Imported182-"+tag;if(!AssetDatabase.IsValidFolder(f))AssetDatabase.CreateFolder("Assets","Imported182-"+tag);var root=new GameObject(tag);var prefabs=new Dictionary<string,GameObject>();MineCartV1.Build(Input,f,root.transform,prefabs,d);MineCartV1.Build(Input,f,root.transform,prefabs,d,true);Check(prefabs.Count==(valid?2:1)&&prefabs.ContainsKey("minecart"),"actual prefab fallback "+tag);if(valid){var p=prefabs["minecart_loaded"];Check(p.GetComponents<Collider>().Length==(tag=="nonSolid"?0:1),"optional collider "+tag);if(tag=="customHeight")Check(Mathf.Abs(p.GetComponent<BoxCollider>().size.y-1.4f)<1e-5,"custom height");if(tag=="circle")Check(p.GetComponent<MeshCollider>().sharedMesh.bounds.size==new Vector3(1,.8f,1),"circle bounds");}UnityEngine.Object.DestroyImmediate(root);names.Add(tag);}
 // Rejected optional must still generate every previous small prop, not only the cart.
 var dir=Path.Combine(Root,"Input183-invalid");Directory.CreateDirectory(dir);File.WriteAllText(Path.Combine(dir,"small_props.json"),raw.Replace("\"mineCartLoadV1\":{\"version\":1","\"mineCartLoadV1\":{\"version\":999"));File.Copy(Path.Combine(Input,"props.csv"),Path.Combine(dir,"props.csv"),true);var rr=new GameObject("invalid all old53");var pp=new Dictionary<string,GameObject>();var ff="Assets/Imported182-invalidAll";AssetDatabase.CreateFolder("Assets","Imported182-invalidAll");SmallPropsV1.Build(dir,ff,rr.transform,Shader.Find("MapSharedProps/Lit"),pp);Check(pp.Count==53&&!pp.ContainsKey("minecart_loaded"),"invalid leaves old53 actual");UnityEngine.Object.DestroyImmediate(rr);File.WriteAllText(Path.Combine(Out,"fallback.json"),"{\"pass\":true,\"invalidOld53Generated\":true,\"cases\":["+string.Join(",",names.Select(n=>"\""+n+"\""))+"]}");}
 static void Studio(){Empty();var plane=GameObject.CreatePrimitive(PrimitiveType.Plane);var mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));mat.color=new Color(.25f,.23f,.20f);plane.GetComponent<Renderer>().sharedMaterial=mat;var sun=new GameObject("diagnostic sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1.3f;sun.shadows=LightShadows.Soft;var c=Cam();foreach(var shape in new[]{"straight","curve"}){var rail=Prop("mine_rail_"+shape);foreach(var id in new[]{"minecart","minecart_loaded"}){var cart=Prop(id);cart.transform.position=shape=="straight"?new Vector3(0,.14f,-1):new Vector3(2-Mathf.Sqrt(2),.14f,-Mathf.Sqrt(2));cart.transform.rotation=Quaternion.Euler(0,shape=="curve"?-45:0,0);Check(Mathf.Abs(cart.GetComponent<Renderer>().bounds.min.y-.115f)<1e-5,"flange height same");var target=cart.transform.position+Vector3.up*.6f;foreach(var view in new[]{"normal","close","opposite"}){sun.transform.rotation=Quaternion.Euler(45,view=="opposite"?150:-30,0);c.transform.position=target+(view=="normal"?new Vector3(0,9,-6.3f):view=="close"?new Vector3(2.2f,2.2f,-3):new Vector3(-2.2f,2.2f,3));c.transform.LookAt(target);Shot(c,shape+"-"+view+"-"+id);}UnityEngine.Object.DestroyImmediate(cart);}UnityEngine.Object.DestroyImmediate(rail);}}
