 [Serializable]class LoadRow{public string id;public int placed,visible,meshes,materials,textures;public long meshBytes,textureBytes;public double cpuMedianMs;}
 static void Load(){var rows=new List<LoadRow>();foreach(var id in new[]{"minecart","minecart_loaded"})foreach(int count in new[]{9,225}){Empty();var c=Cam();c.transform.position=new Vector3(0,24,-20);c.transform.LookAt(Vector3.zero);var root=new GameObject("shared");int side=count==9?3:15;for(int i=0;i<count;i++){var o=Prop(id);o.transform.SetParent(root.transform,false);o.transform.position=new Vector3((i%side-side/2)*2,0,(i/side-side/2)*2);}var rs=root.GetComponentsInChildren<Renderer>();var meshes=root.GetComponentsInChildren<MeshFilter>().Select(x=>x.sharedMesh).Distinct().ToArray();var mats=rs.Select(x=>x.sharedMaterial).Distinct().ToArray();var tx=mats.SelectMany(m=>new[]{m.GetTexture("_BaseMap"),m.GetTexture("_MetallicGlossMap"),m.GetTexture("_BumpMap")}).Distinct().ToArray();Check(meshes.Length==1&&mats.Length==1&&tx.Length==3,"shared assets");var rt=new RenderTexture(640,360,24);rt.Create();c.targetTexture=rt;var times=new List<double>();for(int i=0;i<10;i++){var sw=System.Diagnostics.Stopwatch.StartNew();c.Render();sw.Stop();if(i>=4)times.Add(sw.Elapsed.TotalMilliseconds);}times.Sort();var planes=GeometryUtility.CalculateFrustumPlanes(c);rows.Add(new LoadRow{id=id,placed=count,visible=rs.Count(r=>GeometryUtility.TestPlanesAABB(planes,r.bounds)),meshes=meshes.Length,materials=mats.Length,textures=tx.Length,meshBytes=meshes.Sum(x=>UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(x)),textureBytes=tx.Sum(x=>UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(x)),cpuMedianMs=times[times.Count/2]});c.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}File.WriteAllText(Path.Combine(Out,"load.json"),"{\"gpuMeasured\":false,\"cpuSubmissionNotFrameGuarantee\":true,\"rows\":["+string.Join(",",rows.Select(x=>JsonUtility.ToJson(x)))+"]}");}

 [Serializable]class TextureRow{public string name,path;public int width,height;public bool readable;public long bytes;}
 static void Coexist(){var rows=new List<string>();foreach(int count in new[]{9,225}){Empty();var root=new GameObject("mixed");for(int i=0;i<count;i++){var o=Prop(i%2==0?"minecart":"minecart_loaded");o.transform.SetParent(root.transform,false);o.transform.position=new Vector3((i%15-7)*2,0,(i/15-7)*2);}var mats=root.GetComponentsInChildren<Renderer>().Select(r=>r.sharedMaterial).Distinct().ToArray();var ts=mats.SelectMany(m=>new[]{m.GetTexture("_BaseMap"),m.GetTexture("_MetallicGlossMap"),m.GetTexture("_BumpMap")}).Distinct().Cast<Texture2D>().ToArray();Check(mats.Length==2&&ts.Length==6,"coexist six actual references");var descriptions=ts.Select(t=>JsonUtility.ToJson(new TextureRow{name=t.name,path=AssetDatabase.GetAssetPath(t),width=t.width,height=t.height,readable=t.isReadable,bytes=UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(t)}));rows.Add("{\"placed\":"+count+",\"materials\":2,\"textureReferences\":6,\"textureBytes\":"+ts.Sum(t=>UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(t))+",\"textures\":["+string.Join(",",descriptions)+"]}");}File.WriteAllText(Path.Combine(Out,"coexist.json"),"{\"gpuMeasured\":false,\"rows\":["+string.Join(",",rows)+"]}");}
